    if ((hf && RELAXED.includes(f)) || (ca && CA_RELAXED.includes(f))) continue;
    if (f === 'cart_pick' && CLEAN_PICK_CART.has(id)) continue;
    assert.deepEqual(newEntry[f], oldEntry[f], `${id}: frozen field ${f} changed`);
